def business_days_needed_for_target(start_day_num, target_day_num, weekend_days):
    total_days = target_day_num - start_day_num
    full_weeks, remainder = divmod(total_days, 7)
    business_per_week = 7 - len(set(weekend_days))
    count = full_weeks * business_per_week
    for offset in range(1, remainder + 1):
        if (start_day_num + offset) % 7 not in weekend_days:
            count += 1
    return count

