def count_perfect_numbers_in_range(a, b):
    if b < 2:
        return 0
    sums = [0] * (b + 1)
    for d in range(1, b + 1):
        for multiple in range(2 * d, b + 1, d):
            sums[multiple] += d
    lo = max(a, 2)
    return sum(1 for x in range(lo, b + 1) if sums[x] == x)

